CREATE TABLE t (id INTEGER PRIMARY KEY, v TEXT);
INSERT INTO t (v) VALUES ('auto1');
INSERT INTO t (v) VALUES ('auto2'), ('auto3');
INSERT INTO t VALUES (10, 'ten');
INSERT INTO t VALUES (NULL, 'after ten');
INSERT INTO t VALUES (3, 'duplicate');
INSERT INTO t VALUES (-5, 'negative');
SELECT * FROM t;
SELECT v FROM t WHERE id = 10;
SELECT v FROM t WHERE id > 2 AND id < 11;
SELECT v FROM t WHERE 3 <= id AND id <= 10 ORDER BY id DESC;
SELECT v FROM t WHERE id >= 11 OR id < 0;
SELECT v FROM t WHERE id = 3 AND id = 4;
SELECT v FROM t WHERE id > 9223372036854775807;
SELECT v FROM t ORDER BY id LIMIT 2;
SELECT v FROM t LIMIT 2 OFFSET 2;
CREATE TABLE no_pk (a INTEGER);
CREATE TABLE text_pk (a TEXT PRIMARY KEY);
CREATE TABLE two_pk (a INTEGER PRIMARY KEY, b INTEGER PRIMARY KEY);
CREATE TABLE t (x INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS t (x INTEGER PRIMARY KEY);
